import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.BvHJbMD4.js";const m=JSON.parse('{"title":"Research: The Ibiza Video (The Catalyst)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/ibiza-video.md","filePath":"en/recherche/ibiza-video.md"}'),n={name:"en/recherche/ibiza-video.md"};function r(s,e,h,l,c,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="research-the-ibiza-video-the-catalyst" tabindex="-1">Research: The Ibiza Video (The Catalyst) <a class="header-anchor" href="#research-the-ibiza-video-the-catalyst" aria-label="Permalink to &quot;Research: The Ibiza Video (The Catalyst)&quot;">​</a></h1><p><strong>&quot;Genug ist genug&quot; – How a villa in Ibiza changed Austrian politics forever.</strong></p><p>The Ibiza Video is the indispensable catalyst for the modern part of our mockumentary. Without the images of Heinz-Christian Strache and Johann Gudenus in that fateful night of 2017, the deep insights into the &quot;Horten System&quot; and the subsequent political scandals would likely never have come to light.</p><hr><h2 id="the-incident" tabindex="-1">The Incident <a class="header-anchor" href="#the-incident" aria-label="Permalink to &quot;The Incident&quot;">​</a></h2><p>In May 2019, <em>Der Spiegel</em> and <em>Süddeutsche Zeitung</em> published excerpts from a secretly recorded video. It showed the then FPÖ leader and Vice-Chancellor Heinz-Christian Strache and Johann Gudenus talking to a supposed niece of a Russian oligarch.</p><h3 id="key-statements" tabindex="-1">Key Statements: <a class="header-anchor" href="#key-statements" aria-label="Permalink to &quot;Key Statements:&quot;">​</a></h3><ul><li><strong>&quot;Horten is paying&quot;</strong>: Strache explicitly mentioned Heidi Horten as a donor who allegedly bypasses the Court of Audit through associations.</li><li><strong>&quot;Bypassing the Court of Audit&quot;</strong>: He described a system of donations to associations to avoid transparency laws.</li><li><strong>&quot;Takeover of the Krone&quot;</strong>: The idea of buying the largest Austrian newspaper to influence reporting.</li></ul><hr><h2 id="the-consequences" tabindex="-1">The Consequences <a class="header-anchor" href="#the-consequences" aria-label="Permalink to &quot;The Consequences&quot;">​</a></h2><p>The video led to the immediate collapse of the ÖVP-FPÖ government and triggered a cascade of investigations:</p><ol><li><strong>Resignation of the Government:</strong> Sebastian Kurz ended the coalition.</li><li><strong>Ibiza Committee of Inquiry:</strong> A parliamentary committee that brought the &quot;Thomas Schmid Chats&quot; to light.</li><li><strong>Reform of the Political Parties Act:</strong> As a direct reaction to the &quot;Horten mention,&quot; transparency laws were drastically tightened.</li></ol><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>The Ibiza Video is the &quot;Big Bang&quot; of our narrative. It is the moment when the &quot;Pointillism of Capital&quot; was suddenly illuminated by a harsh, unexpected spotlight. In our film, we use the video not as a political document, but as a &quot;glitch in the system&quot; that reveals the true face of power.</p><hr><p><em>Sources: Reporting by Der Spiegel, Süddeutsche Zeitung, and the final report of the Ibiza Committee of Inquiry.</em></p>',17)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
